use std::ffi::CString;
use std::os::raw::c_char;

extern "C" {
    fn execv(path: *const c_char, argv: *const *const c_char) -> i32;
}

// usage: execv_probe <path> [args...]   -- passes args as the FULL argv (so
// giving zero args yields argc==0 in the child).
fn main() {
    let a: Vec<String> = std::env::args().collect();
    let path = CString::new(a[1].clone()).unwrap();
    let owned: Vec<CString> = a[2..]
        .iter()
        .map(|s| CString::new(s.clone()).unwrap())
        .collect();
    let mut ptrs: Vec<*const c_char> = owned.iter().map(|c| c.as_ptr()).collect();
    ptrs.push(std::ptr::null());
    unsafe {
        execv(path.as_ptr(), ptrs.as_ptr());
    }
    eprintln!("execv failed: {}", std::io::Error::last_os_error());
    std::process::exit(127);
}

